def solve_jumping_disks(length, n):
    grid = [0]*length

    for i in range(0, n):
        grid[i] = 1

    from collections import deque

    queue = deque()
    visited_set = set()

    queue.append((grid.copy(), []))

    while queue:
        entry, moves = queue.popleft()

        entry_tuple = tuple(entry)
        if entry_tuple in visited_set:
            continue

        visited_set.add(entry_tuple)

        if 0 not in entry[(length-n):]:
            return moves

        for i in range(0, len(entry)):
            if entry[i] == 1:
                if (i+1 < len(entry) and entry[i+1]==0):
                    entry_copy = entry.copy()
                    entry_copy[i], entry_copy[i+1] = entry_copy[i+1], entry_copy[i]
                    queue.append((entry_copy, moves + [(i, i+1)]))
                elif (i+2 < len(entry) and entry[i+2]==0):
                    entry_copy = entry.copy()
                    entry_copy[i], entry_copy[i+2] = entry_copy[i+2], entry_copy[i]
                    queue.append((entry_copy, moves + [(i, i+2)]))
                elif (i+3 < len(entry) and entry[i+3]==0):
                    entry_copy = entry.copy()
                    entry_copy[i], entry_copy[i+3] = entry_copy[i+3], entry_copy[i]
                    queue.append((entry_copy, moves + [(i, i+3)]))
                elif (i-1 >= 0 and entry[i-1] == 0):
                    entry_copy = entry.copy()
                    entry_copy[i], entry_copy[i-1] = entry_copy[i-1], entry_copy[i]
                    queue.append((entry_copy, moves + [(i, i-1)]))
    return None

