def n_rooks_valid(board):
    grid = [(i, board[i]) for i in range(0, len(board))]

    for i in range(0, len(grid)):
        row1 = grid[i][0]
        col1 = grid[i][1]

        for j in range(i+1, len(grid)):
            row2 = grid[j][0]
            col2 = grid[j][1]

            if row1 == row2 or col1 == col2:
                return False
    return True

def n_rooks_solutions(n):
    solutions = []

    grid = [0]*n

    def dfs_tree(board, row):
        if row == n:
            if n_rooks_valid(board):
                solutions.append(board.copy())
            return 

        for col in range(0, n):
            board[row] = col
            dfs_tree(board, row+1)
            board[row] = 0
    dfs_tree(grid, 0)
    return solutions

