def solve_sliding_puzzle(board):
    from collections import deque

    queue = deque()
    visited_set = set()

    cols = len(board[0])
    rows = len(board)

    grid = [[0]*cols for _ in range(rows)]

    for row in range(0, rows):
        for col in range(0, cols):
            grid[row][col] = board[row][col]

    flat = list(range(1, rows * cols)) + [0]
    goal = tuple(tuple(flat[r * cols:(r + 1) * cols]) for r in range(rows))

    queue.append((grid, []))

    while queue:

        entry, moves = queue.popleft()
        entry_tuple = tuple(tuple(row) for row in entry)

        if entry_tuple in visited_set:
            continue

        visited_set.add(entry_tuple)

        if entry_tuple == goal:
            return moves

        for row in range(0, rows):
            for col in range(0, cols):
                if entry[row][col] == 0:
                    for drow, dcol in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                        row1 = row + drow
                        col1 = col + dcol

                        if 0 <= row1 < rows and 0 <= col1 < cols:
                            entry_copy = [r.copy() for r in entry]
                            entry_copy[row][col], entry_copy[row1][col1] = \
                                entry_copy[row1][col1], entry_copy[row][col]
                            queue.append((entry_copy, moves + [(row1, col1)]))

    return None

