import random


class TriStatePuzzle(object):

    def __init__(self, board):
        self.board = board

    def get_board(self):
        return self.board

    def perform_move(self, row, col):
        self.board[row][col] = (self.board[row][col] + 1) % 3

        # up
        if (row - 1) >= 0:
            self.board[row - 1][col] = (self.board[row - 1][col] + 1) % 3

        # down
        if (row + 1) < len(self.board):
            self.board[row + 1][col] = (self.board[row + 1][col] + 1) % 3

        # left
        if (col - 1) >= 0:
            self.board[row][col - 1] = (self.board[row][col - 1] + 1) % 3

        # right
        if (col + 1) < len(self.board[0]):
            self.board[row][col + 1] = (self.board[row][col + 1] + 1) % 3


    def scramble(self):
        import random

        for row in range(0, len(self.board)):
            for col in range(0, len(self.board[0])):
                for i in range(random.randrange(3)):
                    self.perform_move(row, col)

    def is_solved(self):
        return all(cell == 0 for row in self.board for cell in row)

    def copy(self):
        return TriStatePuzzle([row.copy() for row in self.board])

    def successors(self):
        for row in range(0, len(self.board)):
            for col in range(0, len(self.board[0])):
                board_copy = self.copy()
                board_copy.perform_move(row, col)
                yield ((row, col), board_copy)

    def find_solution(self):
        from collections import deque

        queue = deque()
        visited_set = set()

        queue.append((self.copy(), []))

        while queue:
            entry, moves = queue.popleft()

            entry_tuple = tuple(tuple(row) for row in entry.get_board())
            if entry_tuple in visited_set:
                continue
            visited_set.add(entry_tuple)

            if entry.is_solved():
                return moves

            for next_move, mod_board in entry.successors():
                queue.append((mod_board, moves + [next_move]))

        return None



def create_tri_puzzle(rows, cols):
    return TriStatePuzzle([[0]*cols for _ in range(rows)])
